import{_ as i,o as a,c as n,aj as t}from"./chunks/framework.BdtAaXf2.js";const c=JSON.parse('{"title":"31-Option 类型","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/31-Option 类型/31-Option 类型.md","filePath":"仓颉入门到实战/31-Option 类型/31-Option 类型.md","lastUpdated":1735725812000,"__rawMarkdown":"# 31-Option 类型\\n\\n## 前言\\n\\n`Option `可以理解为是为我们常用的数据类型进行包装，包装的结果有两个：\\n\\n1. **有值**  `Some`\\n2. **没有值**  `None`\\n\\n`Option` 类型使用 `enum` 定义，它包含两个构造器：`Some` 和 `None`。其中，`Some` 会携带一个参数，表示有值，`None` 不带\\n\\n参数，表示无值。当需要表示某个类型可能有值，也可能没有值的时候，可选择使用 `Option` 类型。\\n\\n## 示例\\n\\n`Option` 类型被定义为一个泛型 `enum` 类型，\\n\\n```javascript\\nenum Option<T> {\\n    | Some(T)\\n    | None\\n}\\n```\\n\\n下面的例子展示了如何定义 `Option` 类型的变量：\\n\\n```javascript\\nlet a: Option<Int64> = Some(100)\\nlet b: ?Int64 = Some(100)\\nlet c: Option<String> = Some(\\"Hello\\")\\nlet d: ?String = None\\n```\\n\\n编译器会用 `Option<T>` 类型的 `Some` 构造器将 `T` 类型的值封装成 `Option<T>` 类型的值（注意：这里并不是类型转换）。例如，下面的定义是合法的（等价于上例中变量 `a`，`b` 和 `c` 的定义）：\\n\\n```javascript\\nlet a: Option<Int64> = 100\\nlet b: ?Int64 = 100\\nlet c: Option<String> = \\"100\\"\\n```\\n\\n在上下文没有明确的类型要求时，无法使用 `None` 直接构造出想要的类型，此时应使用 `None<T>` 这样的语法来构造 `Option<T>` 类型的数据，例如\\n\\n```javascript\\nlet a = None<Int64> // a: Option<Int64>\\nlet b = None<Bool> // b: Option<Bool>\\n```\\n\\n"}'),e={name:"仓颉入门到实战/31-Option 类型/31-Option 类型.md"};function p(l,s,h,k,d,o){return a(),n("div",null,[...s[0]||(s[0]=[t("",15)])])}const g=i(e,[["render",p]]);export{c as __pageData,g as default};
